sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var carePlans = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_care_plan');
    gr.orderByDesc('start_date');
    gr.query();

    while (gr.next()) {

        carePlans.push({
            sys_id: gr.getUniqueValue(),

            care_plan_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_sys_id: gr.getValue('admission'),
            admission: gr.getDisplayValue('admission'),

            care_plan_name: gr.getValue('care_plan_name'),
            care_plan_type: gr.getDisplayValue('care_plan_type'),

            start_date: gr.getValue('start_date'),
            end_date: gr.getValue('end_date'),

            care_plan_status: gr.getDisplayValue('care_plan_status'),

            primary_goal: gr.getValue('primary_goal'),
            notes: gr.getValue('notes'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: carePlans.length,
        care_plans: carePlans
    });

})(request, response);
